local mod=get_mod("information_overload")
local Models=mod:io_dofile("InformationOverload/scripts/mods/InformationOverload/protection_models")
local TeamDamage=mod:io_dofile("InformationOverload/scripts/mods/InformationOverload/team_damage")
local Enemies=mod:io_dofile("InformationOverload/scripts/mods/InformationOverload/enemy_breakdown")
local X={}
local Timeline=mod:io_dofile("InformationOverload/scripts/mods/InformationOverload/combat_timeline")
X.definitions={status="Observed measurements; research saved before 1.0.4 is not kept",selection="All accepted history",averaging="Enemy kills: equal match denominator including recorded zeroes. Damage/distance: pooled observed events. Health: once per distinct locally observed enemy per segment, not per hit.",missing="Absent fields are Not recorded, never zero. Excluded from new measurement denominators.",partial="Full games and accepted partial results: observed intervals only. Data-only, discarded and hidden contributions excluded. Rejoined segments remain separate to avoid pretending overlapping target samples are unique.",health="Reported maximum health, sampled once on first observation. Histogram keys retain the reported numeric precision. Health increases are observed increases, not complete healing attribution.",protection="Resolved target numeric stats plus active buff declarations, without applier attribution. Declarations may be conditional or overridden. No claim that every multiplier is captured.",predictions="Actual local execute result (or labelled calculate fallback) compared to matched server report; agreement is not an independent no-protection baseline or proof of either hypothesis.",models="Additive DR: max(0,1-sum(DR)); multiplicative DR: product(1-DR). Hypothetical amplification applied afterwards. Reference damage 100 is a mathematical input, never a measured weapon baseline.",ehp="Not recorded until independently validated constant-protection cases. Rotten Armour excluded from constant EHP.",distance="Distance from matched calculation unless explicit resolved-report positions are available. 0<=d<5, 5<=d<10, 10<=d<20, d>=20 metres. Kill bands require report-time unit positions. Calculation-distance fallbacks do not enter kill bands. Detailed hit histogram uses floor(distance) metre bins, 100 means 100m or farther.",sessions="Observed ammo-spend calls. Burst ends after more than 0.35 seconds without a shot, weapon switch, reload or observation end. Duration first-to-last shot; a single shot is zero duration. Session shot distribution 128 means 128 or more; duration histogram rounded to tenths, capped at 3600 seconds. Firing-state time is independent; ability presence sampled every 0.1 seconds.",reloads="Action stages, not necessarily whole reloads. Finished means stage refilled ammunition; interrupted means no stage refill; incomplete means observation ended. Round changes may overlap other refills; not an isolated manual transfer claim.",ability="Point-Blank Barrage: sampled active buff time / observed player time; firing overlap uses observed firing-state time; shot share uses observed ammo-spend calls. These have separate denominators.",quality="Supported locally grouped attacks with at least one confirmed enemy hit, and at least one confirmed weakspot hit. Pellets and cleave do not inflate attack denominators. Unmatched confirmations excluded; cancellations/censoring can affect coverage.",lucky="Lucky Bullet observed _leadbelcher_shot flags; saved ammunition is nominal cost skipped by the game, not extra reserve gain. Overlapping other free-ammo conditions are separated as lucky_saved_overlap, not credited as unique Lucky Bullet savings. Critical bullets and sequence-start checks are separate. No streak-derived unconditional rate.",charmed="Charmed Reload setter calls within its actual proc callback; rounds are actual clip increase, limited by magazine/reserve. Zero-round proc calls remain activations.",bounds="128 enemy types; 64 health values/type; 32 weapon keys; 256 hit groups/segment; optional 128-entry trace. Dropped samples counted. Histograms can be incomplete after limits; do not treat as representative without coverage review."}
X.definitions.engagement_distance="Match-wide matched local report counters, independent of the 256 detailed-group cap. Categories stay separate. Close Range uses strict distance < saved close threshold. Curve bands use 0/25/50/75/100% far interpolation weight, with exact close boundary separated. Curve exposure is not talent-attributed damage. Missing distance/kill distance stays outside known-distance denominators. Absent engagement_distance is Not recorded; recording that starts mid-segment covers only subsequent reports."
local function segments(e,out)if e.segments then for _,part in ipairs(e.segments)do segments(part,out)end else out[#out+1]=e end end
local function ratio(n,d)if type(d)=="number"and d>0 then return 100*(n or 0)/d end end
X.definitions.peril="Time-weighted distribution of observed Peril, 101 percentage bins plus weighted mean; with a separate 0.5s timestamped timeline from 0.6.7. Sampled about every 0.1s. Consecutive observations of the same active human Psyker only. Local component and replicated HUD sources labelled separately. Missing, absent and incapacitated intervals are not zero. Remote replication may be delayed or quantised; not validated against a second client."
X.definitions.distance_scope="Local player ranged/explosion reports only; range counters independent of attack timing and detailed sample cap. No teammate distance or ordinary melee. Gradients collected only for Zealot, Veteran and Hive Scum regardless of selected talents; other classes use close/non-close. Explosion distance is owner-to-target at report time, not reconstructed at throw time. Per-weapon range attribution can cover fewer reports than the category totals."
function X.summary(segment)
 local out={status=segment.status,observed_seconds=segment.observed_seconds,ability_uptime_percent=ratio(segment.pbb_seconds,segment.observed_seconds),ability_firing_overlap_percent=ratio(segment.pbb_firing_seconds,segment.firing_seconds),weapons={},peril=segment.peril,peril_timeline=segment.peril_timeline,engagement_distance=segment.engagement_distance,distance_definitions=segment.distance_definitions,distance_status=segment.engagement_distance and "observed_reports"or "Not recorded"}
 for id,w in pairs(segment.weapons or {})do if w.bursts then out.weapons[id]={label=w.label,engagement_distance=w.engagement_distance,shots=w.shots,ability_shot_share_percent=ratio(w.pbb_shots,w.shots),observed_hit_attack_percent=ratio(w.hit_attacks,w.attacks),weakspot_share_of_hit_attacks_percent=ratio(w.weakspot_attacks,w.hit_attacks),lucky_trigger_share_of_ammo_events_percent=ratio(w.lucky_triggers,w.shots),average_shots_per_session=w.bursts.count>0 and w.bursts.shots/w.bursts.count or nil,average_session_seconds=w.bursts.count>0 and w.bursts.duration/w.bursts.count or nil,shot_samples=w.shots,attack_samples=w.attacks,censored_attacks=w.censored_attacks or 0}else out.weapons[id]={label=w.label,engagement_distance=w.engagement_distance}end end
 return out
end
function X.live(data,context)
 local result={context=context,measurements=data,status="ongoing_observation_not_a_completed_result",summary=X.summary(data),hypotheses={}}
 for _,group in ipairs(data.observations or {})do result.hypotheses[#result.hypotheses+1]={group=group.id,estimate=Models.from_declarations(group.snapshot),resolved_stat_comparison=Models.from_snapshot(group.snapshot)}end
 return result
end
function X.build(runs,filters)
 local ok,enemies=pcall(Enemies.build,runs,(filters or {}).enemy_group,(filters or {}).enemy_role,(filters or {}).enemy_scope);if not ok then enemies={status="Unreadable",error=tostring(enemies)}end
 local out={format=1,measurements=true,definitions=X.definitions,filters=filters or {},selected=0,recorded=0,matches={},enemy_summary=enemies}
 -- each match keeps only what its timeline gives, never the timeline itself, and one that cannot be read is listed as unreadable
 local function match(run)
  local row={id=run.id,context=run.context,full=run.full,run_kind=run.run_kind,status=run.measurements and "observed"or run.experimental and "legacy_research"or "Not recorded",segments={}}
  local timeline=run.combat_timeline
  if timeline then row.damage_buckets=Timeline.buckets(timeline,10);row.best_ten_seconds=Timeline.best_window(timeline,10);row.best_kills_before_damage=Timeline.best_streak(run);row.best_kills_before_health_loss=Timeline.best_health_streak(run)end
  if (run.measurements or run.experimental) then out.recorded=out.recorded+1;segments((run.measurements or run.experimental),row.segments);row.hypotheses={};row.summaries={};for _,segment in ipairs(row.segments)do row.summaries[#row.summaries+1]=X.summary(segment)end;row.existing_pbb_ammo_recovered=run.records and run.records.pbb_ammo_mission
   for _,segment in ipairs(row.segments)do for _,group in ipairs(segment.observations or {})do row.hypotheses[#row.hypotheses+1]={group=group.id,estimate=Models.from_declarations(group.snapshot),resolved_stat_comparison=Models.from_snapshot(group.snapshot)}end end
  end;row.damage_capture=TeamDamage.from_run(run);if row.damage_capture then local own=TeamDamage.summary(row.damage_capture,tostring((run.context or {}).character),"total");local matched=0
   -- a segment's totals are counted before the group cap; an older save without them sums its kept groups
   for _,segment in ipairs(row.segments)do local t=segment.observation_totals
    if t then matched=matched+(t.confirmed or 0)-(t.shield_confirmed or 0)
    else for _,group in ipairs(segment.observations or {})do if group.snapshot.armour~="void_shield"then matched=matched+(group.confirmed or 0)end end end end
   row.attribution_coverage={personal_reported_damage=own.reported,matched_experimental_damage=matched}end
  return row
 end
 for _,run in ipairs(runs or {})do if type(run.victory)=="boolean"and not run.data_only and not run.discarded and not run.hidden_contributions and not run.stats_excluded then
  out.selected=out.selected+1;local ok,row=pcall(match,run);if not ok then row={id=run.id,context=run.context,status="Unreadable",error=tostring(row)}end
  out.matches[#out.matches+1]=row
 end end;return out
end
return X
